#!/usr/bin/env node

/**
 * Set Android Subscription Prices Script
 *
 * Changes the price of existing Google Play subscription *base plans* using data
 * from a JSON file generated by generate-product-ids.js (the same format the
 * Apple set-subscription-prices.js and bulk-create-subscriptions-android.js use).
 *
 * For each subscription it:
 *   1. Converts the target USD price into all regional prices (convertRegionPrices).
 *   2. Patches the base plan's regionalConfigs with the new prices.
 *
 * By default the new price applies to NEW subscribers only — existing subscribers
 * keep their price. Pass --migrate-existing to also move current subscribers onto
 * the new price (price increases trigger Google Play's notification/consent flow).
 *
 * Usage:
 *   node set-android-subscription-prices.js <json-file-path> --package <package-name> [options]
 *   npm run set-android-subscription-prices -- product-ids.json --package com.example.app
 *   npm run set-android-subscription-prices -- product-ids.json --package com.example.app --dry-run
 */

require('dotenv').config();
const fs = require('fs');
const googlePlayClient = require('./src/services/googleplay-client');
const logger = require('./src/utils/logger');

// Google Play price-increase modes for migrating existing subscribers.
const PRICE_INCREASE_TYPES = {
  'opt-in': 'PRICE_INCREASE_TYPE_OPT_IN',
  'opt-out': 'PRICE_INCREASE_TYPE_OPT_OUT'
};

/**
 * Convert a USD price string (e.g. "4.99") to a Google Play Money object.
 */
function convertPrice(priceStr) {
  if (priceStr == null) return null;

  const price = parseFloat(priceStr);
  if (isNaN(price)) return null;

  const units = Math.floor(price).toString();
  const nanos = Math.round((price - Math.floor(price)) * 1e9);

  return { currencyCode: 'USD', units, nanos };
}

/**
 * Display help message
 */
function showHelp() {
  console.log(`
Set Android Subscription Prices (Google Play)

Usage:
  node set-android-subscription-prices.js <json-file-path> --package <package-name> [options]
  npm run set-android-subscription-prices -- <json-file-path> --package <package-name> [options]

Arguments:
  json-file-path    Path to the JSON file (output from generate-product-ids.js)

Options:
  --package <name>            Android package name (application ID). Required unless
                              the JSON file has a "packageName". --package-name is
                              accepted as an alias.
  --dry-run                   Preview price changes without writing anything
  --migrate-existing          Also move existing subscribers onto the new price.
                              Without this, only new subscribers get the new price.
  --price-increase-type <t>   Only with --migrate-existing. "opt-in" (default) or
                              "opt-out". Governs the consent flow for price
                              increases (ignored for price decreases).
  --help, -h                  Show this help message

Examples:
  node set-android-subscription-prices.js product-ids.json --package com.example.app
  node set-android-subscription-prices.js product-ids.json --package com.example.app --dry-run
  node set-android-subscription-prices.js product-ids.json --package com.example.app --migrate-existing
  node set-android-subscription-prices.js product-ids.json --package com.example.app \\
    --migrate-existing --price-increase-type opt-out

Process:
  1. Reads the JSON file with subscription data (including USD prices)
  2. Fetches existing subscriptions from Google Play
  3. For each subscription, converts the USD price into all regional prices
  4. Patches the matching base plan's regional prices (updateMask=basePlans)
  5. With --migrate-existing, migrates current subscribers onto the new price
  6. Reports success/failure for each operation

Notes:
  - The base plan targeted is the one whose basePlanId equals the productId with
    dots replaced by dashes (the convention used by bulk-create), or the sole base
    plan if there is exactly one.
  - Regional prices come from Google Play's convertRegionPrices, keyed by USD
    price and cached so repeated prices are only converted once.
  - Existing per-region availability is preserved; only the price is swapped.
  - New-subscriber price changes take effect immediately. Existing-subscriber
    migrations (price increases) run through Google Play's notification period.
`);
}

/**
 * Get the value following a flag, supporting both "--flag value" and "--flag=value".
 */
function getArgValue(args, flag) {
  const eqPrefix = `${flag}=`;
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === flag) {
      return i + 1 < args.length ? args[i + 1] : null;
    }
    if (a.startsWith(eqPrefix)) {
      return a.slice(eqPrefix.length);
    }
  }
  return null;
}

// Flags that take a value ("--flag value" or "--flag=value").
const VALUE_FLAGS = new Set(['--package', '--package-name', '--price-increase-type']);

// Boolean flags that take no value.
const BOOLEAN_FLAGS = new Set(['--dry-run', '--migrate-existing', '--help', '-h']);

/**
 * Validate CLI args and collect positionals in a single pass: unknown flags,
 * value flags missing a value, boolean flags given a value, and extra positionals
 * are all reported. Returns { errors: string[], positionals: string[] }.
 */
function validateArgs(args) {
  const errors = [];
  const positionals = [];

  for (let i = 0; i < args.length; i++) {
    const a = args[i];

    if (!a.startsWith('-')) {
      positionals.push(a);
      continue;
    }

    const eqIdx = a.indexOf('=');
    const flag = eqIdx === -1 ? a : a.slice(0, eqIdx);
    const inlineValue = eqIdx === -1 ? null : a.slice(eqIdx + 1);

    if (VALUE_FLAGS.has(flag)) {
      if (inlineValue !== null) {
        if (inlineValue === '') {
          errors.push(`Option "${flag}" requires a value (got "${a}")`);
        }
      } else {
        const next = args[i + 1];
        if (next === undefined || next.startsWith('-')) {
          errors.push(`Option "${flag}" requires a value`);
        } else {
          i++; // consume the value so it isn't treated as a positional
        }
      }
    } else if (BOOLEAN_FLAGS.has(flag)) {
      if (inlineValue !== null) {
        errors.push(`Option "${flag}" does not take a value`);
      }
    } else {
      errors.push(`Unknown option: "${a}"`);
    }
  }

  if (positionals.length === 0) {
    errors.push('JSON file path is required');
  } else if (positionals.length > 1) {
    errors.push(`Unexpected extra argument(s): ${positionals.slice(1).join(', ')}`);
  }

  return { errors, positionals };
}

/**
 * Fetch converted regional prices from Google Play for a USD price.
 * @returns {object} { convertedRegionPrices, convertedOtherRegionsPrice, regionsVersion }
 */
async function getRegionalPrices(packageName, usdPrice) {
  const result = await googlePlayClient.convertRegionPrices(packageName, usdPrice);

  return {
    convertedRegionPrices: result.convertedRegionPrices || {},
    convertedOtherRegionsPrice: result.convertedOtherRegionsPrice || null,
    regionsVersion: result.regionVersion?.version || null
  };
}

/**
 * Pick the base plan to re-price for a subscription. Preference order:
 *   1. the explicit "basePlanId" on the JSON entry, if it matches a real base plan
 *   2. the base plan whose id matches the dot-to-dash productId convention
 *   3. the sole base plan, if there's exactly one
 * Returns null if it can't be determined unambiguously.
 */
function resolveTargetBasePlan(existingSub, subscription) {
  const basePlans = existingSub.basePlans || [];
  if (basePlans.length === 0) return null;

  if (subscription.basePlanId) {
    const explicit = basePlans.find(bp => bp.basePlanId === subscription.basePlanId);
    if (explicit) return explicit;
  }

  const conventionId = subscription.productId.replace(/\./g, '-');
  const byConvention = basePlans.find(bp => bp.basePlanId === conventionId);
  if (byConvention) return byConvention;

  if (basePlans.length === 1) return basePlans[0];

  return null; // ambiguous: multiple base plans, none matching
}

/**
 * Build the full basePlans array for a patch, swapping the target base plan's
 * regional prices while leaving every other base plan untouched (the patch
 * replaces the whole repeated field, so all base plans must be sent back).
 * Existing per-region availability is preserved; only price changes. Regions Play
 * now supports that weren't on the base plan before are added (availability on).
 *
 * @returns {object} { basePlans, regionCodes } where regionCodes are the regions
 *   that received the new price (used for migrating existing subscribers).
 */
function buildPatchedBasePlans(existingSub, targetBasePlanId, convertedRegionPrices, convertedOtherRegionsPrice) {
  const priceByRegion = {};
  for (const [regionCode, priceData] of Object.entries(convertedRegionPrices)) {
    priceByRegion[regionCode] = priceData.price || priceData;
  }

  const basePlans = (existingSub.basePlans || []).map(bp => {
    if (bp.basePlanId !== targetBasePlanId) {
      return bp; // untouched
    }

    const seen = new Set();
    const regionalConfigs = (bp.regionalConfigs || []).map(rc => {
      seen.add(rc.regionCode);
      const newPrice = priceByRegion[rc.regionCode];
      return newPrice ? { ...rc, price: newPrice } : rc;
    });

    for (const [regionCode, price] of Object.entries(priceByRegion)) {
      if (!seen.has(regionCode)) {
        regionalConfigs.push({ regionCode, newSubscriberAvailability: true, price });
      }
    }

    const updated = { ...bp, regionalConfigs };

    if (convertedOtherRegionsPrice) {
      updated.otherRegionsConfig = {
        ...(bp.otherRegionsConfig || { newSubscriberAvailability: true }),
        usdPrice: convertedOtherRegionsPrice.usdPrice,
        eurPrice: convertedOtherRegionsPrice.eurPrice
      };
    }

    return updated;
  });

  return { basePlans, regionCodes: Object.keys(priceByRegion) };
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.includes('--help') || args.includes('-h')) {
    showHelp();
    process.exit(0);
  }

  // Validate flag syntax and collect the positional JSON path up front.
  const { errors: argErrors, positionals } = validateArgs(args);
  if (argErrors.length > 0) {
    argErrors.forEach(e => console.error(`Error: ${e}`));
    console.error('');
    showHelp();
    process.exit(1);
  }
  const jsonPath = positionals[0];

  const dryRun = args.includes('--dry-run');
  const migrateExisting = args.includes('--migrate-existing');

  // Validate value-flag contents.
  const valueErrors = [];

  // --package / --package-name (alias). CLI wins over the JSON file's packageName.
  const cliPackage = getArgValue(args, '--package') ?? getArgValue(args, '--package-name');
  if (cliPackage !== null && !/^[A-Za-z0-9][A-Za-z0-9._]*$/.test(cliPackage)) {
    valueErrors.push(`--package "${cliPackage}" is not a valid Android application ID`);
  }

  // --price-increase-type only applies when migrating existing subscribers.
  const priceIncreaseTypeArg = (getArgValue(args, '--price-increase-type') || 'opt-in').toLowerCase();
  if (!PRICE_INCREASE_TYPES[priceIncreaseTypeArg]) {
    valueErrors.push(`--price-increase-type must be one of: ${Object.keys(PRICE_INCREASE_TYPES).join(', ')} (got "${priceIncreaseTypeArg}")`);
  }
  if (getArgValue(args, '--price-increase-type') !== null && !migrateExisting) {
    console.warn('Warning: --price-increase-type has no effect without --migrate-existing\n');
  }

  if (valueErrors.length > 0) {
    valueErrors.forEach(e => console.error(`Error: ${e}`));
    console.error('');
    process.exit(1);
  }

  const priceIncreaseType = PRICE_INCREASE_TYPES[priceIncreaseTypeArg];

  if (!fs.existsSync(jsonPath)) {
    console.error(`Error: File not found: ${jsonPath}`);
    process.exit(1);
  }

  console.log('='.repeat(70));
  console.log('Set Android Subscription Prices (Google Play)');
  console.log('='.repeat(70));

  if (dryRun) {
    console.log('\n[DRY-RUN MODE] No changes will be made\n');
  }

  try {
    let data;
    try {
      data = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
    } catch (parseError) {
      throw new Error(`Could not parse JSON file "${jsonPath}": ${parseError.message}`);
    }

    if (!Array.isArray(data.subscriptionGroups)) {
      throw new Error(
        'Invalid input file: expected a "subscriptionGroups" array ' +
        '(is this the output of generate-product-ids.js?)'
      );
    }

    // Resolve package name: CLI flag wins, otherwise the JSON file's packageName.
    const packageName = cliPackage || data.packageName;
    if (!packageName) {
      throw new Error(
        'No package name provided. Pass --package <name> or include "packageName" in the JSON file.'
      );
    }

    console.log(`Source file: ${jsonPath}`);
    console.log(`Package: ${packageName}${cliPackage ? ' (from --package)' : ''}`);
    console.log(`Migrate existing subscribers: ${migrateExisting}${migrateExisting ? ` (${priceIncreaseTypeArg})` : ''}`);

    // Fetch existing subscriptions (need the full resource: base plans + configs).
    console.log('\nFetching existing subscriptions from Google Play...');
    const existing = await googlePlayClient.getSubscriptions(packageName);
    const existingSubs = existing.subscriptions || [];
    const subscriptionMap = new Map();
    existingSubs.forEach(s => subscriptionMap.set(s.productId, s));
    console.log(`Existing Subscriptions: ${existingSubs.length}`);

    const results = {
      total: 0,
      success: 0,
      migrated: 0,
      failed: 0,
      noPrice: 0,
      notFound: 0,
      noBasePlan: 0,
      errors: []
    };

    // Cache converted regional prices keyed by USD price string.
    const regionalPricesCache = {};

    // Rate-limit only *between* live writes.
    let priorWrite = false;

    console.log('\n' + '-'.repeat(70));
    console.log('Setting Prices');
    console.log('-'.repeat(70));

    for (const group of data.subscriptionGroups) {
      console.log(`\nGroup: ${group.groupName}`);

      if (!Array.isArray(group.subscriptions)) {
        console.log(`    [SKIP] Group "${group.groupName}" has no "subscriptions" array`);
        continue;
      }

      for (const subscription of group.subscriptions) {
        results.total++;
        const productId = subscription.productId;
        const price = subscription.price;

        console.log(`\n  Product: ${productId}`);

        const existingSub = subscriptionMap.get(productId);
        if (!existingSub) {
          console.log(`    [NOT FOUND] Subscription not found in Google Play`);
          results.notFound++;
          continue;
        }

        // Treat only null/undefined as missing so a legitimate $0 isn't dropped.
        if (price == null) {
          console.log(`    [NO PRICE] No price specified in JSON`);
          results.noPrice++;
          continue;
        }

        const targetBasePlan = resolveTargetBasePlan(existingSub, subscription);
        if (!targetBasePlan) {
          const count = (existingSub.basePlans || []).length;
          console.log(`    [NO BASE PLAN] Could not determine which base plan to re-price (found ${count}; none match "${productId.replace(/\./g, '-')}")`);
          results.noBasePlan++;
          continue;
        }

        console.log(`    Base Plan: ${targetBasePlan.basePlanId} (state: ${targetBasePlan.state || 'unknown'})`);
        console.log(`    Target USD Price: $${price}`);

        // Rate-limit between live writes (skip for dry-run and before the first).
        if (!dryRun) {
          if (priorWrite) {
            await new Promise(resolve => setTimeout(resolve, 1000));
          }
          priorWrite = true;
        }

        try {
          const usdPrice = convertPrice(price);
          if (!usdPrice) {
            throw new Error(`Invalid price "${price}"`);
          }

          // Convert the USD price to all regional prices (cached per price point).
          const priceKey = String(price);
          let regional = regionalPricesCache[priceKey];
          if (!regional) {
            console.log(`    Converting USD $${price} to regional prices...`);
            regional = await getRegionalPrices(packageName, usdPrice);
            regionalPricesCache[priceKey] = regional;
            console.log(`    Got ${Object.keys(regional.convertedRegionPrices).length} regions (regionsVersion: ${regional.regionsVersion})`);
          }

          const { basePlans, regionCodes } = buildPatchedBasePlans(
            existingSub,
            targetBasePlan.basePlanId,
            regional.convertedRegionPrices,
            regional.convertedOtherRegionsPrice
          );

          if (dryRun) {
            console.log(`    [DRY-RUN] Would set $${price} USD across ${regionCodes.length} regions on base plan "${targetBasePlan.basePlanId}"`);
            if (migrateExisting) {
              console.log(`    [DRY-RUN] Would migrate existing subscribers (${priceIncreaseTypeArg}) in ${regionCodes.length} regions`);
            }
            results.success++;
            continue;
          }

          // Patch the base plan prices (new subscribers).
          console.log(`    Patching base plan prices for ${regionCodes.length} regions...`);
          await googlePlayClient.patchSubscription(
            packageName,
            productId,
            { packageName, productId, basePlans },
            'basePlans',
            regional.regionsVersion
          );
          console.log(`    [SUCCESS] Updated base plan price for new subscribers`);
          results.success++;

          // Optionally migrate existing subscribers onto the new price.
          if (migrateExisting) {
            const now = new Date().toISOString();
            const regionalPriceMigrations = regionCodes.map(regionCode => ({
              regionCode,
              oldestAllowedPriceVersionTime: now,
              priceIncreaseType
            }));

            console.log(`    Migrating existing subscribers (${priceIncreaseTypeArg}) in ${regionCodes.length} regions...`);
            await googlePlayClient.migrateBasePlanPrices(
              packageName,
              productId,
              targetBasePlan.basePlanId,
              regionalPriceMigrations,
              regional.regionsVersion
            );
            console.log(`    [MIGRATED] Existing subscribers moved to the new price`);
            results.migrated++;
          }

        } catch (error) {
          console.log(`    [ERROR] ${error.message}`);
          results.failed++;
          results.errors.push({ productId, error: error.message });
        }
      }
    }

    // Print summary
    console.log('\n' + '='.repeat(70));
    console.log('Summary');
    console.log('='.repeat(70));
    console.log(`\nSubscriptions Processed: ${results.total}`);
    console.log(`  Prices Set Successfully: ${results.success}`);
    if (migrateExisting) {
      console.log(`  Existing Subscribers Migrated: ${results.migrated}`);
    }
    console.log(`  Failed: ${results.failed}`);
    console.log(`  Not Found: ${results.notFound}`);
    console.log(`  No Base Plan Resolved: ${results.noBasePlan}`);
    console.log(`  No Price Specified: ${results.noPrice}`);

    if (dryRun) {
      console.log('\n[DRY-RUN] No changes were made. Remove --dry-run to execute.');
    }

    if (results.errors.length > 0) {
      console.log('\nErrors:');
      results.errors.forEach(err => {
        console.log(`  - ${err.productId}: ${err.error}`);
      });
    }

    if (results.failed > 0) {
      process.exit(1);
    }

  } catch (error) {
    console.error(`\nFatal error: ${error.message}`);
    logger.error('Set Android subscription prices failed:', error);
    process.exit(1);
  }
}

// Run only when invoked directly; exporting the pure helpers lets them be unit
// tested without making API calls.
if (require.main === module) {
  main().catch((error) => {
    console.error(`\nUnexpected error: ${error.message}`);
    logger.error('Set Android subscription prices crashed:', error);
    process.exit(1);
  });
}

module.exports = {
  convertPrice,
  resolveTargetBasePlan,
  buildPatchedBasePlans
};
